mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)',re.M)
edges={m:[x for x in imp.findall(open(p,encoding='utf-8',errors='replace').read()) if x in mods] for m,p in mods.items()}
seen={'AlgebraicJacobian'}; q=collections.deque(seen)
while q:
    c=q.popleft()
    for n in edges.get(c,[]):
        if n not in seen: seen.add(n); q.append(n)
un=sorted(set(mods)-seen)
def ol(m): return '.lake/build/lib/lean/'+m.replace('.','/')+'.olean'
stale=[]
missing=[]
for m,p in mods.items():
    o=ol(m)
    if not os.path.exists(o): missing.append(m)
    elif os.path.getmtime(o) < os.path.getmtime(p): stale.append(m)
print("ROOTED:",len(seen),"UNROOTED:",len(un),"TOTAL:",len(mods))
print("olean MISSING:",len(missing))
for m in sorted(missing): print("   miss",m, "UNROOTED" if m in set(un) else "ROOTED")
