for m in sorted(stale): print("   stale",m, "UNROOTED" if m in set(un) else "ROOTED")
print("--- unrooted modules WITH an olean (built earlier / directly) ---")
for m in un:
    print("   ",m, "olean" if os.path.exists(ol(m)) else "NO-olean")
# extra oleans with no source
srcmods=set(mods)
