for dp,_,fs in os.walk('.lake/build/lib/lean/AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.olean'):
            p=os.path.join(dp,f)
            m=os.path.relpath(p,'.lake/build/lib/lean')[:-6].replace('/','.')
            if m not in srcmods: extra.append(m)
print("oleans with NO source (deleted modules):",len(extra))
for m in sorted(extra)[:30]: print("   orphan",m)
