import os,re,glob
def strip(s):
    # remove /-- ... -/ and /- ... -/ block comments (non-nested approx, handles most)
    out=[];i=0;n=len(s);depth=0
    while i<n:
        if s.startswith('/-',i): depth+=1;i+=2;continue
        if s.startswith('-/',i) and depth>0: depth-=1;i+=2;out.append(' ');continue
        if depth==0 and s.startswith('--',i):
            j=s.find('\n',i); i=n if j<0 else j; continue
        if depth==0: out.append(s[i])
        elif s[i]=='\n': out.append('\n')
        i+=1
    return ''.join(out)
pats=['AlgebraicJacobian/Picard/Pic0Chart*.lean','AlgebraicJacobian/Picard/DivRep*.lean',
      'AlgebraicJacobian/Picard/DivisorFamily*.lean','AlgebraicJacobian/Picard/DivScheme*.lean',
      'AlgebraicJacobian/Picard/Pic0SigmaSheaf.lean','AlgebraicJacobian/Picard/Pic0ChartAtlasParamFree.lean']
files=sorted({f for p in pats for f in glob.glob(p)})
decl=re.compile(r'^(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+)*(class|structure)\s+(?!inductive|abbrev)([A-Za-z0-9_\'.]+)',re.M)
res=[]
for f in files:
    s=strip(open(f,encoding='utf-8',errors='replace').read())
    for m in decl.finditer(s):
        res.append((m.group(1),m.group(2),f))
print("seam files scanned:",len(files))
print("REAL class/structure decls on seam:",len(res))
for k,n,f in sorted(res,key=lambda t:(t[2],t[1])): print(f"{k:9s} {n:38s} {f}")
